 column.onpointermove=event=>{if(!drag||drag.column!==column||event.pointerId!==drag.id)return;if(Math.abs(event.clientY-drag.origin)>4)drag.moved=true;const viewport=root.getBoundingClientRect();if(event.clientY>viewport.bottom-24)root.scrollTop+=16;else if(event.clientY<viewport.top+90)root.scrollTop-=16;const current=Math.max(rangeStart,Math.min(rangeEnd-SLOT,rangeStart+Math.floor((event.clientY-column.getBoundingClientRect().top)/(SLOT*MINUTE))*SLOT));drag.current=current;drag.highlight.style.top=((Math.min(current,drag.anchor)-rangeStart)*MINUTE)+'px';drag.highlight.style.height=((Math.abs(current-drag.anchor)+SLOT)*MINUTE)+'px';const selected=selection(day,drag.anchor,current,timezone);drag.highlight.textContent=selected?selected.value.slice(11)+' · '+selected.duration+' мин':'Перевод часов';};
