 if(!readOnly)for(let slot=rangeStart/SLOT;slot<rangeEnd/SLOT;slot++){const minute=slot*SLOT,h=Math.floor(minute/60),m=minute%60,time=String(h).padStart(2,'0')+':'+String(m).padStart(2,'0');const button=node('button',undefined,'time-slot');button.type='button';button.style.top=((minute-rangeStart)*MINUTE)+'px';button.style.height=(SLOT*MINUTE)+'px';button.setAttribute('aria-label','Создать урок '+day+' в '+time);button.title=day+' · '+time;const valid=instants(day,minute,timezone).length===1;button.disabled=!valid||day<now.day||(day===now.day&&minute<now.minute);if(!valid)button.title='Неоднозначное или отсутствующее время из-за перевода часов';button.onclick=event=>{if(event.detail!==0&&Date.now()<suppressClickUntil)return;onCreate(day+'T'+time)};button.onpointerdown=event=>{if(event.pointerType!=='mouse'||event.button!==0||button.disabled)return;event.preventDefault();clearSelection();const highlight=node('div',time+' · '+SLOT+' мин','calendar-selection');highlight.style.top=((minute-rangeStart)*MINUTE)+'px';highlight.style.height=(SLOT*MINUTE)+'px';column.append(highlight);drag={id:event.pointerId,anchor:minute,current:minute,column,highlight,origin:event.clientY,moved:false};column.setPointerCapture(event.pointerId)};column.append(button)}
